const D = { energy:.55, density:.5, scale:1, speed:1, wind:.35, alpha:.6, hue:210, x:.12, y:.95, style:'smoke', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'drift';
const isInc=st==='incense', isInk=st==='ink', isFF=st==='flow_field';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sp=P.speed, sc=clp(P.scale,0.25,2.4);
const sx=P.x*W, sy=P.y*Hh;
let envR=1, envA=1;
if(act==='billow'){ envR=0.5+1.4*Math.pow(K.intensity,1.3); envA=0.75+0.6*K.intensity; }
else if(act==='dissipate'){ envA=0.35+0.85*Math.pow(clp(0.5+0.5*Math.sin(K.t*0.023+0.6),0,1),1.2); }

// ---- pre-blurred puff sprites, built once (never blur the canvas — 12ms/frame) ----
if(!S.sp||S.spSeed!==P.seed){
  const SZ=64; S.sp=[];
  for(let k=0;k<3;k++){
    const g=createGraphics(SZ,SZ); g.pixelDensity(1); g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
    if(k===0){ for(let r=26;r>0;r-=2){ g.fill(0,0,100,3.4); g.circle(32,32,r*2); } }
    else if(k===1){ for(let l=0;l<5;l++){ const a2=fr(k*9+l)*6.283, d2=6+fr(k*9+l+40)*9;
        for(let r=15;r>0;r-=2){ g.fill(0,0,100,2.6); g.ellipse(32+Math.cos(a2)*d2,32+Math.sin(a2)*d2,r*2.4,r*1.3); } } }
    else { for(let r=26;r>6;r-=2){ g.fill(0,0,100,3.0); g.circle(32,32,r*2); }
           for(let r=10;r>0;r-=2){ g.fill(0,0,0,2.2); g.circle(32,32,r*2); } }   // hollow vortex core
    g.filter(BLUR,3);
    S.sp.push(g);
  }
  S.spSeed=P.seed;
}

// ---- curl-noise velocity: v = (dPsi/dy, -dPsi/dx) — divergence-free, so it really curls ----
const T=K.t*sp, w1=fr(1)*6.283, w2=fr(2)*6.283, w3=fr(3)*6.283;
const kk=2.6/(u*sc);
const psi=(x,y)=>
   Math.sin(x*kk*1.0+T*0.21+w1)*Math.cos(y*kk*1.3-T*0.17)
 + 0.55*Math.sin(x*kk*2.3-y*kk*1.7+T*0.37+w2)
 + 0.30*Math.cos(x*kk*4.1+y*kk*3.3-T*0.53+w3);
const eps=u*0.006;
const vel=(x,y)=>{
  const dy=(psi(x,y+eps)-psi(x,y-eps))/(2*eps), dx=(psi(x+eps,y)-psi(x-eps,y))/(2*eps);
  return [dy,-dx];
};

// ---- flow_field: the advection field itself, made visible. No puffs. ----
if(isFF){
  const cols=26, rows=Math.max(8,Math.round(26*Hh/W));
  strokeWeight(Math.max(0.5,u*0.0014*sc));
  for(let cxi=0;cxi<cols;cxi++) for(let ry=0;ry<rows;ry++){
    const x=(cxi+0.5)/cols*W, y=(ry+0.5)/rows*Hh;
    const v=vel(x,y), sp2=Math.hypot(v[0],v[1])*u*0.6+P.wind;
    const ln=u*0.026*sc*(0.3+1.5*en)*clp(Math.abs(sp2)*0.9,0.15,2.2);
    const ang=Math.atan2(v[1]+0.30,v[0]+P.wind*0.9);
    const f=clp(Math.abs(sp2)*0.7,0,1);
    stroke(md(H+f*70,360),lrp(20,68,f),lrp(48,100,f),clp((16+62*f)*al*(0.35+0.9*en)*envA,0,90));
    line(x,y,x+Math.cos(ang)*ln,y+Math.sin(ang)*ln);
  }
  blendMode(BLEND); drawingContext.shadowBlur=0; noStroke(); noTint();
} else {

// ---- puffs advected through the field ----
const n=Math.max(6,Math.round(lrp(30,130,dn)*(isInc?0.42:1)));
if(!S.pp||S.pn!==n||S.pseed!==P.seed){
  const old=S.pp||[]; S.pp=[];
  for(let i=0;i<n;i++){ const l0=fr(i*5+1);
    S.pp.push(old[i]||{x:sx+(fr(i*5+6)-0.5)*u*0.55*l0+P.wind*u*0.5*l0, y:sy-u*0.6*l0*(0.4+0.9*en),
                       vx:0, vy:0, l:l0, r:fr(i*5+2), s:Math.floor(fr(i*5+3)*3), o:fr(i*5+4)}); }
  S.pn=n; S.pseed=P.seed;
}
const dt=clp(K.t-(S.pt==null?K.t:S.pt),0,0.09); S.pt=K.t;   // real-time integration, survives a t0 reset
const rate=(0.11+0.20*en)*sp*envR;
const buoy=-u*(0.05+0.30*en)*(isInc?1.35:1);
const wind=P.wind*u*(0.16+0.30*en)+Math.sin(K.t*0.137)*u*0.03;
const jet=u*0.10*sc;

for(let i=0;i<n;i++){
  const p=S.pp[i];
  p.l+=dt*rate*(0.6+p.r*0.9);
  if(p.l>=1||p.x<-u*0.3||p.x>W+u*0.3||p.y<-u*0.3){
    p.l=0; p.r=fr(i*5+2+Math.floor(K.t*7)%97); p.o=fr(i*5+4+Math.floor(K.t*11)%89);
    p.x=sx+(p.o-0.5)*jet*(isInc?0.25:1); p.y=sy+(p.r-0.5)*jet*0.5;
    p.vx=0; p.vy=0;
    continue;
  }
  const v=vel(p.x,p.y);
  // laminar near the source, turbulent once it has risen — the real incense transition
  const turb=isInc?clp((sy-p.y)/(u*0.30),0,1):1;
  const cA=u*(0.30+1.35*en)*turb;
  p.vx=lrp(p.vx, v[0]*cA+wind, 0.10);
  p.vy=lrp(p.vy, v[1]*cA+buoy*(0.4+0.9*p.l), 0.10);
  p.x+=p.vx*dt; p.y+=p.vy*dt;
}

// draw far/old puffs first so the young dense core reads on top
const ord=S.pp.map((p,i)=>i).sort((a,b)=>S.pp[b].l-S.pp[a].l);
if(!isInk) blendMode(BLEND);
for(let q=0;q<ord.length;q++){
  const p=S.pp[ord[q]];
  const life=clp(p.l,0,1);
  const grow=lrp(0.30,1.9,Math.pow(life,0.62));
  const sz=u*lrp(0.06,0.20,p.r)*sc*grow*(isInc?0.55:1);
  const fade=Math.sin(Math.PI*Math.pow(life,0.8));           // in and out, never a hard pop
  const aa=clp((isInk?26:isInc?15:20)*fade*al*envA*(0.4+0.9*en)*(1+A.lowmid*0.35),0,44);
  if(aa<0.6) continue;
  const rimlit=clp(1-life*1.2,0,1);
  push(); translate(p.x,p.y);
  rotate(Math.atan2(p.vy,p.vx)*0.5 + K.t*(0.06+p.r*0.19)*sp + p.o*6.283);
  if(isInk){ tint(md(H+8,360), lrp(30,6,life), lrp(18,44,life), aa*2.1); }
  else { tint(md(H+lrp(14,-8,life),360), lrp(isInc?8:18,4,life), lrp(58,96,life)*lrp(0.75,1,rimlit), aa*2.1); }
  imageMode(CENTER);
  image(S.sp[p.s], 0, 0, sz*lrp(1.5,1,life), sz*lrp(0.8,1,life));
  imageMode(CORNER);
  pop();
}
noTint();
}

blendMode(BLEND); drawingContext.shadowBlur=0; noTint(); noStroke();
